"""Pricing helpers for order lines."""

TAX_RATE = 0.08


def subtotal(lines):
    total = 0
    for line in lines:
        total += line["price"] * line["qty"]
    return total


def total_with_tax(lines):
    total = 0
    for line in lines:
        total += line["price"] * line["qty"]
    return round(total * (1 + TAX_RATE), 2)


def apply_discount(amount, percent):
    """Reduce amount by percent (for example 10 means 10%)."""
    return amount - amount * percent / 10


def apply_coupon(amount, coupon):
    """Apply a coupon such as {"code": "SPRING", "percent": 20}."""
    percent = coupon["percent"]
    return amount - amount * percent / 10

